T={(0,0),(1,1),(1,2),(2,0),(2,1)}
K={(0,1),(1,1),(1,2),(2,0),(2,2)}
def norm(S):
 mi=min(x for x,y in S); mj=min(y for x,y in S); return {(x-mi,y-mj) for x,y in S}
variants=[]
for trans in [lambda x,y:(x,y),lambda x,y:(x,-y),lambda x,y:(-x,y),lambda x,y:(-x,-y),lambda x,y:(y,x),lambda x,y:(y,-x),lambda x,y:(-y,x),lambda x,y:(-y,-x)]:
 variants.append(norm({trans(x,y) for x,y in K}))
print([(i,v==T,v) for i,v in enumerate(variants)])

# demo1 key colors normalized 4x4 and output blocks
K1={(0,2):3,(1,0):2,(1,2):3,(1,3):4,(2,0):2,(2,1):1,(2,2):1,(3,0):2,(3,3):4}
O1={(0,0):2,(0,1):2,(0,2):2,(1,1):1,(2,1):1,(2,2):3,(2,3):3,(3,0):4,(3,2):4}
# dihedral mapping normalized square
ops=[lambda r,c:(r,c),lambda r,c:(r,3-c),lambda r,c:(3-r,c),lambda r,c:(3-r,3-c),lambda r,c:(c,r),lambda r,c:(c,3-r),lambda r,c:(3-c,r),lambda r,c:(3-c,3-r)]
for i,f in enumerate(ops):
 d={f(r,c):v for (r,c),v in K1.items()}
 print(i, d==O1, sum(O1.get(k)==v for k,v in d.items()),len(d))
